.PGBRK {page-break-after:always}
.COVER-TITLE {TEXT-ALIGN:CENTER; color: #ff8625; FONT-FAMILY:gulim; FONT-WEIGHT: bold; FONT-SIZE: 28px; LETTER-SPACING: -1px; line-height:28px; height:45px; WIDTH:600px;}
